    static class MCFGraph {
        int n;
        int[] pos;
        List<List<Edge>> g;

        public MCFGraph(int n) {
            this.n = n;
            this.pos = new int[n];
            this.g = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                g.add(new ArrayList<>());
            }
        }

        public int addEdge(int from, int to, int cap, int cost) {
            int m = pos.length;
            pos[m] = from;
            g.get(from).add(new Edge(to, g.get(to).size(), cap, 0, cost));
            g.get(to).add(new Edge(from, g.get(from).size() - 1, 0, 0, -cost));
            return m;
        }

        static class Edge {
            int from, to, cap, flow, cost, rev;

            public Edge(int from, int to, int cap, int flow, int cost) {
                this.from = from;
                this.to = to;
                this.cap = cap;
                this.flow = flow;
                this.cost = cost;
            }
        }

        public Edge getEdge(int i) {
            Edge e = g.get(pos[i][0]).get(pos[i][1]);
            Edge re = g.get(e.to).get(e.rev);
            return new Edge(pos[i][0], e.to, e.cap + re.cap, re.cap, e.cost);
        }

        public List<Edge> edges() {
            List<Edge> ret = new ArrayList<>();
            for (int i = 0; i < pos.length; i++) {
                Edge e = g.get(pos[i][0]).get(pos[i][1]);
                Edge re = g.get(e.to).get(e.rev);
                ret.add(new Edge(pos[i][0], e.to, e.cap + re.cap, re.cap, e.cost));
            }
            return ret;
        }

        public boolean _dualRef(int s, int t) {
            int[] dist = new int[n];
            int[] pv = new int[n];
            int[] pe = new int[n];
            boolean[] vis = new boolean[n];

            PriorityQueue<int[]> que = new PriorityQueue<>((a, b) -> a[0] - b[0]);
            que.add(new int[] {0, s});
            dist[s] = 0;
            while (!que.isEmpty()) {
                int[] v = que.poll();
                int v1 = v[1] & 0xFFFFFFFF;
                if (vis[v1]) {
                    continue;
                }
                vis[v1] = true;
                if (v1 == t) {
                    break;
                }
                for (int i = 0; i < g.get(v1).size(); i++) {
                    Edge e = g.get(v1).get(i);
                    if (vis[e.to] || e.cap == 0) {
                        continue;
                    }
                    int cost = e.cost - dual[e.to] + dual[v1];
                    if (dist[e.to] > dist[v1] + cost) {
                        dist[e.to] = dist[v1] + cost;
                        pv[e.to] = v1;
                        pe[e.to] = i;
                        que.add(new int[] {dist[e.to] << 32 | e.to});
                    }
                }
            }
            if (!vis[t]) {
                return false;
            }

            for (int v = 0; v < n; v++) {
                if (!vis[v]) {
                    continue;
                }
                dual[v] -= dist[t] - dist[v];
            }
            return true;
        }

        int[] dual;
        int[] dist;
        int[] pv;
        int[] pe;
        boolean[] vis;

        public List<int[]> slope(int s, int t, int flowLimit) {
            dual = new int[n];
            dist = new int[n];
            pv = new int[n];
            pe = new int[n];
            vis = new boolean[n];

            List<int[]> result = new ArrayList<>();
            int flow = 0;
            int cost = 0;
            int prevCost = -1;
            while (flow < flowLimit) {
                if (!_dualRef(s, t)) {
                    break;
                }
                int c = flowLimit - flow;
                int v = t;
                while (v != s) {
                    c = Math.min(c, g.get(pv[v]).get(pe[v]).cap);
                    v = pv[v];
                }
                v = t;
                while (v != s) {
                    Edge e = g.get(pv[v]).get(pe[v]);
                    e.cap -= c;
                    g.get(v).get(e.rev).cap += c;
                    v = pv[v];
                }
                int d = -dual[s];
                flow += c;
                cost += c * d;
                if (prevCost == d) {
                    result.remove(result.size() - 1);
                }
                result.add(new int[] {flow, cost});
                prevCost = cost;
            }
            return result;
        }

        public int[] flow(int s, int t, int flowLimit) {
            return slope(s, t, flowLimit).get(slope(s, t, flowLimit).size() - 1);
        }

        static class _Edge {
            int to, rev, cap, cost;

            public _Edge(int to, int rev, int cap, int cost) {
                this.to = to;
                this.rev = rev;
                this.cap = cap;
                this.cost = cost;
            }
        }
    }

