import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {

    static class Edge {
        int from, to, cap, flow;
        Edge(int from, int to, int cap, int flow) {
            this.from = from;
            this.to = to;
            this.cap = cap;
            this.flow = flow;
        }
    }

    static class Dinic {
        int n;
        ArrayList<Edge>[] links;
        int[] depth;
        int[] progress;
        int[][] pos;

        Dinic(int n) {
            this.n = n;
            links = new ArrayList[n];
            for (int i = 0; i < n; i++) {
                links[i] = new ArrayList<>();
            }
            depth = new int[n];
            progress = new int[n];
            pos = new int[n][];
        }

        void addEdge(int from, int to, int cap) {
            pos[from] = Arrays.copyOf(pos[from], pos[from].length + 1);
            links[from].add(new Edge(from, to, cap, 0));
            links[to].add(new Edge(to, from, 0, 0));
        }

        void bfs(int s) {
            Arrays.fill(depth, -1);
            depth[s] = 0;
            int[] q = new int[n];
            int front = 0, rear = 0;
            q[rear++] = s;
            while (front < rear) {
                int v = q[front++];
                for (Edge e : links[v]) {
                    if (e.cap > 0 && depth[e.to] < 0) {
                        depth[e.to] = depth[v] + 1;
                        q[rear++] = e.to;
                    }
                }
            }
        }

        int dfs(int v, int t, int flow) {
            if (v == t) return flow;
            for (int i = progress[v]; i < links[v].size(); i++) {
                progress[v] = i;
                Edge e = links[v].get(i);
                if (e.cap > 0 && depth[v] >= depth[e.to]) {
                    int d = dfs(e.to, t, Math.min(flow, e.cap));
                    if (d == 0) continue;
                    e.flow += d;
                    links[e.to].get(links[v].indexOf(e)).flow -= d;
                    return d;
                }
            }
            return 0;
        }

        int flow(int s, int t) {
            int flow = 0;
            while (true) {
                bfs(s);
                if (depth[t] < 0) return flow;
                Arrays.fill(progress, 0);
                while (true) {
                    int d = dfs(s, t, Integer.MAX_VALUE);
                    if (d == 0) break;
                    flow += d;
                }
            }
        }

        Edge getEdge(int i) {
            Edge e = links[pos[i][0]].get(pos[i][1]);
            Edge re = links[e.to].get(links[pos[i][0]].indexOf(e));
            return new Edge(pos[i][0], e.to, e.cap + re.flow, re.flow);
        }

        Edge[] getEdges() {
            int M = pos.length;
            Edge[] res = new Edge[M];
            for (int i = 0; i < M; i++) {
                res[i] = getEdge(i);
            }
            return res;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        StringTokenizer st;
        int N = Integer.parseInt(br.readLine());
        int M = 3;
        int[] A = new int[M];
        int[] B = new int[M];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < M; i++) {
            A[i] = Integer.parseInt(st.nextToken());
        }
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < M; i++) {
            B[i] = Integer.parseInt(st.nextToken());
        }
        int ans1 = 0;
        for (int i = 0; i < M; i++) {
            ans1 += Math.min(A[i], B[(i + 1) % M]);
        }
        Dinic dinic = new Dinic(2 * M + 2);
        int s = 2 * M;
        int t = 2 * M + 1;
        for (int i = 0; i < M; i++) {
            dinic.addEdge(s, i, N);
            dinic.addEdge(M + i, t, B[i]);
            dinic.addEdge(i, M + i, A[i]);
            dinic.addEdge(i, M + (i - 1) % M, A[i]);
        }
        int ans2 = N - dinic.flow(s, t);
        pw.println(ans2 + " " + ans1);
        pw.close();
    }
}

