        boolean[] isPrime = new boolean[6000];
        Arrays.fill(isPrime, true);
        for (int i = 2; i < 6000; i++) {
            for (int j = 2; j <= Math.sqrt(i); j++) {
                if (isPrime[j] && i % j == 0) {
                    isPrime[i] = false;
                    break;
                }
            }
