        public static Map<Integer, Integer> factor(int n) {
            Map<Integer, Integer> d = new HashMap<>();
            for (int p : primes) {
                if (p * p > n) {
                    break;
                }
                if (n % p == 0) {
                    int c = 0;
                    while (n % p == 0) {
                        n = n / p;
                        c++;
                    }
                    d.put(p, c);
                }
            }
            if (n > 1) {
                d.put(n, 1);
            }
            return d;
        }

        public static List<Integer> factors(int n) {
            Map<Integer, Integer> d = factor(n);
            List<Integer> answer = new ArrayList<>();
            answer.add(1);
            for (int p : d.keySet()) {
                List<Integer> a2 = new ArrayList<>();
                for (int x : answer) {
                    for (int i = 0; i <= d.get(p); i++) {
                        a2.add(x * (int) Math.pow(p, i));
                    }
                }
                answer = a2;
            }
            return answer;
        }

