public class Main {
    static final int MOD = 1000000007;
    static final int MAX = 100000;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        int T = 1;
        for (int t = 0; t < T; t++) {
            solve(br, pw);
        }
        pw.close();
    }

    static void solve(BufferedReader br, PrintWriter pw) throws IOException {
        StringTokenizer st = new StringTokenizer(br.readLine());
        int P = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());
        int[] k = new int[P];
        for (int i = 0; i < P; i++) {
            k[i] = (int) ((long) K * i % P);
        }

        if (K == 0) {
            pw.println(pow(P, P - 1, MOD));
            return;
        }
        if (K == 1) {
            pw.println(pow(P, P, MOD));
            return;
        }

        boolean[] f = new boolean[P];
        int[] c = new int[MAX];
        int ans = 1;
        for (int i = 0; i < P; i++) {
            if (f[i]) continue;

            int cnt = 1;
            int u = i;
            f[u] = true;
            while (!f[k[u]]) {
                u = k[u];
                f[u] = true;
                cnt++;
            }

            c[cnt]++;
        }

        for (int i = 2; i < MAX; i++) {
            if (c[i] != 0) {
                int cnt = i * c[i] + 1;
                ans = (int) ((long) ans * pow(cnt, c[i], MOD) % MOD);
            }
        }

        pw.println(ans);
    }

    static long pow(long a, long b, int mod) {
        long res = 1;
        while (b > 0) {
            if ((b & 1) == 1) {
                res = (res * a) % mod;
            }
            a = (a * a) % mod;
            b >>= 1;
        }
        return res;
    }
}
