        for (int i = 0; i < sArray.length; i++) {
            int t = k - 1 - sArray[i];
            int ind = binarySearchCount(s1Array, s1Array.length, t);
            int r = s1Array[ind - 1];
            int rt = s1Array[s1Array.length - 1];
            t = ans;
            ans = Math.max((r + sArray[i]) % k, (sArray[i] + rt) % k);
            ans = Math.max(ans, t);
        }
        System.out.println(ans);
    }

    static int binarySearchCount(int[] arr, int n, int key) {
        int left = 0;
        int right = n - 1;
        int count = 0;
        while (left <= right) {
            int mid = (right + left) / 2;
            if (arr[mid] <= key) {
                count = mid + 1;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return count;
    }

