    static long invnum(int[] seq) {
        int N = seq.length;
        long res = 0;
        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                if (seq[i] > seq[j]) {
                    res++;
                }
            }
        }
        return res;
    }

    static long naive(int N, long k, boolean flag) {
        long res = 0;
        for (int[] p : getPermutations(N)) {
            for (int[] q : getPermutations(N)) {
                if (((Arrays.compare(p, q) < 0) || (!flag)) && (invnum(p) - invnum(q) > k)) {
                    res++;
                }
            }
        }
        return res;
    }

    static long[][] getPermutations(int N) {
        long[][] res = new long[N][N];
        for (int i = 0; i < N; i++) {
            res[i][0] = i;
        }
        for (int i = 1; i < N; i++) {
            for (int j = 0; j < N; j++) {
                for (int k = 0; k < N; k++) {
                    if (res[j][i - 1] > res[k][i - 1]) {
                        res[j][i] = res[k][i - 1];
                        res[k][i] = res[j][i - 1];
                    }
                }
            }
        }
        return res;
    }

    static long solve(int N, long k, boolean flag) {
        if (memo[N][flag ? 1 : 0][(int) k] != 0) {
            return memo[N][flag ? 1 : 0][(int) k];
        }
        if (N == 1) {
            long res = -1;
            if (flag) {
                res = 0;
            } else {
                if (k < 0) {
                    res = 1;
                } else {
                    res = 0;
                }
            }
            memo[N][flag ? 1 : 0][(int) k] = res;
            return res;
        }
        long invnum_INF = (N * (N - 1)) / 2;
        if (k < -invnum_INF - 1) {
            return solve(N, -invnum_INF - 1, flag);
        }
        if (k >= invnum_INF) {
            memo[N][flag ? 1 : 0][(int) k] = 0;
            return 0;
